def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Endgame exploitation: if opponent is still likely to cooperate, defect.
    remaining = 100 - n
    opp_c_total = sum(1 for a in opp if a == 'C')
    opp_c_ratio = opp_c_total / n

    if remaining <= 2:
        if opp_c_ratio > 0.35:
            return 'D'
        return 'D' if rng.random() < 0.6 else 'C'

    # Clear pattern detection
    last8 = opp[-8:] if n >= 8 else opp
    d8 = sum(1 for a in last8 if a == 'D')
    c8 = len(last8) - d8

    # Always-defector / highly exploitative: defect, with rare probes
    if n >= 8 and d8 >= 7:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Always cooperator / very nice: mostly cooperate, but exploit lightly near end
    if n >= 8 and c8 >= 7:
        if remaining <= 10 and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Opponent cooperation rate recent
    recent_len = min(12, n)
    recent = opp[-recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_len

    last_opp = opp[-1]
    last_me = me[-1]

    # Detect opponent's defection runs
    def_run = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            def_run += 1
        else:
            break

    coop_run = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            coop_run += 1
        else:
            break

    # If opponent just defected after cooperating, retaliate, then forgive
    if last_opp == 'D':
        if def_run >= 4:
            # sustained defection: punish harder
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if def_run == 1:
            # Single defection: one retaliation then return to cooperation
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        # 2-3 defections in a row
        if recent_ratio > 0.55 and rng.random() < 0.5:
            return 'C'
        return 'D'

    # Opponent cooperated last
    if coop_run >= 2:
        # Opponent is cooperating steadily; cooperate but occasionally test
        if n % 19 == 0 and rng.random() < 0.2:
            return 'D'
        return 'C'

    # Mixed: use forgiving tit-for-tat with mild anti-exploitation
    if recent_ratio >= 0.6:
        return 'C'

    # Low recent cooperation but last was C: defect to gain, but keep some cooperation
    if recent_ratio < 0.3:
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Moderate: mirror-ish with forgiveness
    if last_me == 'D' and last_opp == 'C':
        return 'C'
    return 'C' if rng.random() < 0.8 else 'D'
